!function(t){function a(a){for(var p,i,n=a[0],o=a[1],c=a[2],g=0,k=[];g<n.length;g++)i=n[g],Object.prototype.hasOwnProperty.call(e,i)&&e[i]&&k.push(e[i][0]),e[i]=0;for(p in o)Object.prototype.hasOwnProperty.call(o,p)&&(t[p]=o[p]);for(u&&u(a);k.length;)k.shift()();return m.push.apply(m,c||[]),r()}function r(){for(var t,a=0;a<m.length;a++){for(var r,i=m[a],n=!0,o=1;o<i.length;o++)r=i[o],0!==e[r]&&(n=!1);n&&(m.splice(a--,1),t=p(p.s=i[0]))}return t}function p(a){if(i[a])return i[a].exports;var r=i[a]={i:a,l:!1,exports:{}};return t[a].call(r.exports,r,r.exports,p),r.l=!0,r.exports}var i={},e={9:0},m=[];p.m=t,p.c=i,p.d=function(t,a,r){p.o(t,a)||Object.defineProperty(t,a,{enumerable:!0,get:r})},p.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},p.t=function(t,a){if(1&a&&(t=p(t)),8&a)return t;if(4&a&&"object"==typeof t&&t&&t.__esModule)return t;var r=Object.create(null);if(p.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:t}),2&a&&"string"!=typeof t)for(var i in t)p.d(r,i,function(a){return t[a]}.bind(null,i));return r},p.n=function(t){var a=t&&t.__esModule?function(){return t.default}:function(){return t};return p.d(a,"a",a),a},p.o=function(t,a){return Object.prototype.hasOwnProperty.call(t,a)},p.p="";var n=window.webpackJsonp=window.webpackJsonp||[],o=n.push.bind(n);n.push=a,n=n.slice();for(var c=0;c<n.length;c++)a(n[c]);var u=o;m.push([21,0]),r()}({21:function(t,a,r){"use strict";r.r(a);var p=r(0);Object(p.a)("uk","army",r(22),r(1))},22:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"“丘吉尔”步兵坦克","description":"<h6>综述：</h6><p>“丘吉尔”（Churchill)(A22)坦克是英军在二战中最后一款步兵坦克，是属于中重型坦克，它于1941年6月正式装备英军，二战期间一共生产了5640辆，产量相当大。此系列坦克从Ⅰ型开始共有18种型号，其中主要型号是Ⅰ-VIII型，各型号分别在火炮、装甲或动力装置上都作了一些改进。“丘吉尔”步兵坦克装甲厚，整车较重，车体也较大，车速很低，后期型号的正面装甲厚度甚至超过了德军的虎式坦克，是典型的装甲厚、车速低，随步兵作战的步兵坦克；该坦克最大特点是悬挂系统采用了11个小直径负重轮，其优点是战斗中当个别小负重轮被击毁时，也不影响坦克的行动，但缺点是越野行进时坦克会有较大的巅簸，使乘员感到不舒适；该坦克，“丘吉尔”步兵坦克是英军在二战中、后期的重要装备，一直跟随英军战斗到二战结束。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}丘吉尔Ⅱ型步兵坦克<br>1942年4月，英国苏格兰地区隶属英军第16装甲旅第66坦克营的一辆丘吉尔Ⅱ型步兵坦克{{image}}imgs/uk/army/uk_army_tankch_11.jpg{{text}}丘吉尔Ⅲ型步兵坦克<br>1943年3月，北非突尼斯战场，英军25军坦克旅的一辆丘吉尔Ⅲ型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_12.jpg{{text}}丘吉尔Ⅲ型步兵坦克<br>1943年12月，在列宁格勒前线一辆未知单位的丘吉尔Ⅲ型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_13.jpg","description":"<h6>早期型（Ⅰ-Ⅵ型）丘吉尔步兵坦克</h6><p>二战期间，Ⅰ-Ⅴ型丘吉尔步兵坦克共生产了3000多辆，其中Ⅱ型产量 1127辆，Ⅲ型产量675辆，Ⅳ型产量1622辆，Ⅴ型产量241辆。</p><p>早期型坦克参数：</p><p>车长：7.42m，车宽：2.74m, 车高：3.25m，车重：约39t，乘员：5人；</p><p>最高车速：24km/h，最大行程：145km；</p><p>装甲厚度：16-102mm；</p><p>武器装备：</p><p>Ⅰ型：一门2磅火炮和一门76mm榴弹炮</p><p>Ⅱ型：一门2磅火炮和一挺MG机枪。</p><p>Ⅲ型：1门6磅火炮，炮塔采用新式的焊接结构。</p><p>Ⅳ型：1门6磅火炮，但炮塔采用浇铸结构。</p><p>Ⅴ型：1门95mm榴弹炮。</p><p>Ⅵ型：1门英国75mm火炮。</p><p>此外，各型坦克都装备1-2挺7.92mm机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统每侧有11个小直径的负重轮。</li><li>炮塔有一门主炮和一挺机枪，车体前方有另一门火炮或一挺机枪。</li></ol></span>","caption":""},{"image":"{{text}}丘吉尔VII型步兵坦克<br>隶属英军某独立装甲旅的一辆丘吉尔VII型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_21.jpg{{text}}丘吉尔VII型步兵坦克<br>1944年7月，隶属英军第6护卫坦克旅第第4手榴弹护卫队第3中队的一辆丘吉尔VII型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_22.jpg{{text}}丘吉尔VII型步兵坦克<br>1945年4月，隶属英军第34独立装甲旅的一辆丘吉尔VII型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_23.jpg","description":"<h6>后期型（VII-XI型）丘吉尔步兵坦克</h6><p>从VII型开始，丘吉尔步兵坦克整车都作了重新设计，坦克的炮塔增大了，悬挂系统安装了履带防尘装置，动力系统采用了新研制的变速箱，使坦克的机动性和可靠性都得到了提升，坦克装甲也加厚了，防护能力也得到加强，但车速有所下降，由于可载更多油料，行程也得到提高。</p><p>后期型坦克参数：</p><p>车长：7.54m，车宽：2.74m, 车高：3.35m，车重：约40.6t，乘员：5人；</p><p>最高车速：20km/h，最大行程：350km；</p><p>装甲厚度：25-152mm；</p><p>武器装备：</p><p>VII型：一门75mm火炮。</p><p>VIII型：1门95mm榴弹炮</p><p>IX型、X型：与Ⅵ型火炮相同，在Ⅵ型基础上进行装甲加固。</p><p>XI型：与Ⅴ型火炮相同，在Ⅴ型基础上进行装甲加固。</p><p>此外，各型坦克都装备1挺7.92mm机枪。</p>","caption":""},{"image":"{{text}}丘吉尔AVRE型步兵坦克<br>1944年7月，在法国诺曼底战场，隶属英军第253工程连的一辆丘吉尔AVRE型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_31.jpg{{text}}丘吉尔AVRE型步兵坦克<br>在英国本土隶属皇家工程部队某突击团的一辆丘吉尔AVRE型步兵坦克。{{image}}imgs/uk/army/uk_army_tankch_32.jpg","description":"<h6>丘吉尔AVRE型步兵坦克</h6><p>该型坦克是英国皇家陆军工兵部队专用的一种坦克，它的炮塔装备了一种290mm口径的迫击炮，可发射装有20kg炸药量的炮弹，具有强大破坏力，作直接摧毁对手坚固的碉堡用。</p>","caption":""},{"image":"{{text}}丘吉尔喷火坦克（燃料储存在与坦克脱离的拖车中）{{image}}imgs/uk/army/uk_army_tankch_33.jpg{{text}}丘吉尔AVRE型工程坦克（安装有推土铲，装备皇家工程部队）{{image}}imgs/uk/army/uk_army_tankch_34.jpg{{text}}丘吉尔Ⅱ型架桥坦克{{image}}imgs/uk/army/uk_army_tankch_35.jpg","description":"<h6>丘吉尔变形坦克</h6><p>丘吉尔步兵坦克除了有多种型号外，还有很多不同的变形坦克，其中有喷火坦克，其外装燃料可满足80次喷射，喷射距离最远可达110米，是二战期间最好的喷火坦克。丘吉尔有三款架桥坦克，还有工程坦克、扫雷坦克等，这些坦克都在二战中发挥了不少作用。</p>","caption":""}],"part2title":"战场上的丘吉尔步兵坦克","part2description":"<p>丘吉尔步兵坦克第一次参战是在1942年8月迪耶普登陆战，坦克随加拿大第14陆军坦克团抢滩，但临靠岸时就遭到德军火炮的猛烈攻击，一些坦克靠了岸又无法拖上陡峭的海岸，在滩头的一些坦克又频频出现机械故障，由此坦克不是被击毁，就是被遗弃，第一次参战就以惨败告终。随后在1942年10月，6辆丘吉尔Ⅲ型步兵坦克被运到北非战场，参加了第二次阿拉曼战役，在德军反坦克炮火中，坦克的厚装甲经受了考验，一辆丘吉尔坦克被8发炮弹击中仍安然无恙，由此坦克良好的防护性能得到了确认。此后在北非战场、诺曼底战场与法国战场上，丘吉尔步兵坦克与德军的坦克交战，德军的Ⅲ号与Ⅳ号坦克基本不是对手，与虎式和豹式坦克是互有胜负，其中1943年4月在北非战场，英军以损失二辆丘吉尔步兵坦克的代价击伤缴获了一辆德军虎式坦克；在诺曼底登陆后，在卡昂附近高地的战斗中，英军以损失24辆丘吉尔步兵坦克代价击毁了9辆德军的虎式和豹式坦克。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankch_41.jpg","description":"在英格兰某基地进行训练的英军丘吉尔步兵坦克，前面一辆是Ⅰ型，在车体前方安装了一门76mm的榴弹炮，后面是Ⅱ型，将榴弹炮拆除装上了一挺7.92mm机枪。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_42.jpg","description":"英军某部队的丘吉尔Ⅱ型步兵坦克正在英格兰南部怀特岛进行登陆训练。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_43.jpg","description":"英军某部队的丘吉尔步兵坦克正在进行水陆两栖登陆演习。后面一辆应该是Ⅰ型坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_44.jpg","description":"1943年北非突尼斯，英军丘吉尔Ⅲ型步兵坦克正在公路上行进，奔赴战场。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_45.jpg","description":"1944年6月，意大利战场，英军第31军坦克旅的丘吉尔Ⅳ步兵坦克正掩护步兵对德军发动攻击。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_46.jpg","description":"1944年7月意大利战场，英军第51皇家坦克团的丘吉尔VII型步兵坦克正在作战斗前准备。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_47.jpg","description":"1944年意大利战场，英军一辆丘吉尔VII步兵坦克正在进入一个村庄。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_48.jpg","description":"1944年，行进在荷兰一村庄的英军第4近卫步兵营的丘吉尔Ⅵs型步兵坦克，跟随坦克行进的是英军萨克福第1步兵营的士兵。注意坦克车体与炮塔外都有附加履带作防护装甲。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_49.jpg","description":"1945年初，某英军坦克旅的丘吉尔步兵坦克正在向德国深纵进发。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_50.jpg","description":"英国首相丘吉乐丘吉尔看着以自己命名的步兵坦克向前线开发。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_51.jpg","description":"1945年光复巴黎阅兵，为盟军作先导的就是丘吉尔步兵坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_52.jpg","description":"英军一辆丘吉尔AVRE坦克正在进入一个刚收复的小镇。","caption":""},{"image":"imgs/uk/army/uk_army_tankch_53.jpg","description":"由于壕沟很深，英军只能将两辆丘吉尔架桥坦克叠放一起进行架桥操作。","caption":""}]}')}});